28	func postJSON(t *testing.T, h http.Handler, url string, body any) (*httptest.ResponseRecorder, map[string]any) {
29		t.Helper()
30		var r *http.Request
31		switch b := body.(type) {
32		case string:
33			r = httptest.NewRequest(http.MethodPost, url, strings.NewReader(b))
34		case []byte:
35			r = httptest.NewRequest(http.MethodPost, url, bytes.NewReader(b))
36		default:
37			raw, _ := json.Marshal(b)
38			r = httptest.NewRequest(http.MethodPost, url, bytes.NewReader(raw))
39		}
40		if body != nil {
41			r.Header.Set("Content-Type", "application/json")
42		}
43		w := httptest.NewRecorder()
44		h.ServeHTTP(w, r)
45		var decoded map[string]any
46		if w.Body.Len() > 0 {
47			_ = json.Unmarshal(w.Body.Bytes(), &decoded)
48		}
49		return w, decoded
50	}
