52	func doRequest(t *testing.T, h http.Handler, method, url string) (*httptest.ResponseRecorder, map[string]any) {
53		t.Helper()
54		w := httptest.NewRecorder()
55		h.ServeHTTP(w, httptest.NewRequest(method, url, nil))
56		var decoded map[string]any
57		if w.Body.Len() > 0 {
58			_ = json.Unmarshal(w.Body.Bytes(), &decoded)
59		}
60		return w, decoded
61	}
