103	func TestPostRejectsBadInput(t *testing.T) {
104		h, s := newTestHandler(t)
105		url := "/v1/documents/doc1/changes"
106		if _, err := s.PostChanges("doc1", []events.Change{
107			{ID: "existing", DeviceID: "dev", Payload: json.RawMessage(`{"v":1}`)},
108		}); err != nil {
109			t.Fatal(err)
110		}
111	
112		cases := []struct {
113			name        string
114			contentType string
115			body        string
116			wantStatus  int
117		}{
118			{"wrong content type", "text/plain", `{"deviceId":"d","changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
119			{"missing content type", "", `{"deviceId":"d","changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
120			{"content type with json suffix", "application/vnd.api+json", `{"deviceId":"d","changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
121			{"malformed json", "application/json", `{"deviceId":"d","changes":[`, http.StatusBadRequest},
122			{"trailing content", "application/json", `{"deviceId":"d","changes":[{"id":"a","payload":1}]}garbage`, http.StatusBadRequest},
123			{"empty deviceId", "application/json", `{"deviceId":"","changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
124			{"missing deviceId", "application/json", `{"changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
125			{"numeric deviceId", "application/json", `{"deviceId":7,"changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
126			{"empty changes", "application/json", `{"deviceId":"d","changes":[]}`, http.StatusBadRequest},
127			{"missing changes", "application/json", `{"deviceId":"d"}`, http.StatusBadRequest},
128			{"empty id", "application/json", `{"deviceId":"d","changes":[{"id":"","payload":1}]}`, http.StatusBadRequest},
129			{"numeric id", "application/json", `{"deviceId":"d","changes":[{"id":123,"payload":1}]}`, http.StatusBadRequest},
130			{"missing payload", "application/json", `{"deviceId":"d","changes":[{"id":"a"}]}`, http.StatusBadRequest},
131			{"duplicate ids in batch", "application/json", `{"deviceId":"d","changes":[{"id":"a","payload":1},{"id":"a","payload":2}]}`, http.StatusBadRequest},
132			{"conflicting existing", "application/json", `{"deviceId":"d","changes":[{"id":"existing","payload":2}]}`, http.StatusConflict},
133			{"conflict device mismatch", "application/json", `{"deviceId":"other","changes":[{"id":"existing","payload":{"v":1}}]}`, http.StatusConflict},
134		}
135	
136		for _, tc := range cases {
137			t.Run(tc.name, func(t *testing.T) {
138				r := httptest.NewRequest(http.MethodPost, url, strings.NewReader(tc.body))
139				if tc.contentType != "" {
140					r.Header.Set("Content-Type", tc.contentType)
141				}
142				w := httptest.NewRecorder()
143				h.ServeHTTP(w, r)
144	
145				if w.Code != tc.wantStatus {
146					t.Fatalf("status = %d, want %d, body = %s", w.Code, tc.wantStatus, w.Body.String())
147				}
148				if ct := w.Header().Get("Content-Type"); ct != "application/json" {
149					t.Fatalf("error content type = %q", ct)
150				}
151				var errBody map[string]string
152				if err := json.Unmarshal(w.Body.Bytes(), &errBody); err != nil || errBody["error"] == "" {
153					t.Fatalf("error body = %s", w.Body.String())
154				}
155			})
156		}
157	}
