159	func TestPostRejectsNonStringAndBatchZeroWrite(t *testing.T) {
160		h, s := newTestHandler(t)
161	
162		// Numeric id instead of string.
163		w, _ := postJSON(t, h, "/v1/documents/doc/changes", `{"deviceId":"d","changes":[{"id":123,"payload":1}]}`)
164		if w.Code != http.StatusBadRequest {
165			t.Fatalf("numeric id status = %d", w.Code)
166		}
167	
168		// Batch with duplicate id must write nothing: seed a valid batch, then send
169		// a mixed bad batch, then verify listing only contains the seed.
170		w, _ = postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
171			"deviceId": "dev",
172			"changes":  []any{map[string]any{"id": "ok1", "payload": map[string]any{"n": 1}}},
173		})
174		if w.Code != 200 {
175			t.Fatal(w.Body.String())
176		}
177		w, _ = postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
178			"deviceId": "dev",
179			"changes": []any{
180				map[string]any{"id": "bad-a", "payload": map[string]any{"n": 2}},
181				map[string]any{"id": "bad-a", "payload": map[string]any{"n": 3}},
182			},
183		})
184		if w.Code != 400 {
185			t.Fatalf("dup batch status = %d", w.Code)
186		}
187		rows, _, err := s.ListChanges("doc", 0, 100)
188		if err != nil {
189			t.Fatal(err)
190		}
191		if len(rows) != 1 || rows[0].ID != "ok1" {
192			t.Fatalf("zero-write violated: %+v", rows)
193		}
194	}
