196	func TestPostIdempotentAndConflictHTTP(t *testing.T) {
197		h, s := newTestHandler(t)
198	
199		w, _ := postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
200			"deviceId": "dev",
201			"changes":  []any{map[string]any{"id": "x", "payload": map[string]any{"k": "v"}}},
202		})
203		if w.Code != 200 {
204			t.Fatal(w.Body.String())
205		}
206	
207		// Identical repost: 200, created false, same cursor.
208		w, body := postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
209			"deviceId": "dev",
210			"changes":  []any{map[string]any{"id": "x", "payload": map[string]any{"k": "v"}}},
211		})
212		if w.Code != 200 {
213			t.Fatalf("repost status = %d body = %s", w.Code, w.Body.String())
214		}
215		r := body["results"].([]any)[0].(map[string]any)
216		if r["created"] != false || r["cursor"].(float64) != 1 {
217			t.Fatalf("repost result = %v", r)
218		}
219	
220		// Conflicting repost: 409 and zero additional writes.
221		w, _ = postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
222			"deviceId": "dev",
223			"changes": []any{
224				map[string]any{"id": "y", "payload": map[string]any{"n": 2}},
225				map[string]any{"id": "x", "payload": map[string]any{"k": "different"}},
226			},
227		})
228		if w.Code != http.StatusConflict {
229			t.Fatalf("conflict status = %d body = %s", w.Code, w.Body.String())
230		}
231		rows, _, _ := s.ListChanges("doc", 0, 100)
232		if len(rows) != 1 {
233			t.Fatalf("conflict batch wrote rows: %+v", rows)
234		}
235	}
