237	func TestGetPagination(t *testing.T) {
238		h, _ := newTestHandler(t)
239		for i := 0; i < 5; i++ {
240			w, _ := postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
241				"deviceId": "dev",
242				"changes":  []any{map[string]any{"id": fmt.Sprintf("id%d", i), "payload": map[string]any{"i": i}}},
243			})
244			if w.Code != 200 {
245				t.Fatal(w.Body.String())
246			}
247		}
248	
249		// Defaults: no params -> up to 100, ascending.
250		w, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc/changes")
251		if w.Code != 200 {
252			t.Fatal(w.Body.String())
253		}
254		list := body["changes"].([]any)
255		if len(list) != 5 || body["nextCursor"].(float64) != 5 {
256			t.Fatalf("default list = %v next=%v", list, body["nextCursor"])
257		}
258		first := list[0].(map[string]any)
259		if first["id"] != "id0" || first["deviceId"] != "dev" || first["cursor"].(float64) != 1 {
260			t.Fatalf("first row = %v", first)
261		}
262		if first["payload"].(map[string]any)["i"].(float64) != 0 {
263			t.Fatalf("payload = %v", first["payload"])
264		}
265	
266		// Page with after/limit.
267		w, body = doRequest(t, h, http.MethodGet, "/v1/documents/doc/changes?after=2&limit=2")
268		if w.Code != 200 {
269			t.Fatal(w.Body.String())
270		}
271		list = body["changes"].([]any)
272		if len(list) != 2 {
273			t.Fatalf("page len = %d", len(list))
274		}
275		if list[0].(map[string]any)["id"] != "id2" || list[1].(map[string]any)["id"] != "id3" {
276			t.Fatalf("page ids = %v", list)
277		}
278		if body["nextCursor"].(float64) != 4 {
279			t.Fatalf("nextCursor = %v", body["nextCursor"])
280		}
281	
282		// after at high-water mark: empty, nextCursor == after.
283		w, body = doRequest(t, h, http.MethodGet, "/v1/documents/doc/changes?after=5")
284		if w.Code != 200 || len(body["changes"].([]any)) != 0 || body["nextCursor"].(float64) != 5 {
285			t.Fatalf("tail: code=%d body=%s", w.Code, w.Body.String())
286		}
287	
288		// Unknown document: empty list, cursor 0.
289		w, body = doRequest(t, h, http.MethodGet, "/v1/documents/ghost/changes?after=50")
290		if w.Code != 200 || len(body["changes"].([]any)) != 0 || body["nextCursor"].(float64) != 0 {
291			t.Fatalf("unknown: code=%d body=%s", w.Code, w.Body.String())
292		}
293	}
