330	func TestConcurrentPostsHTTP(t *testing.T) {
331		h, _ := newTestHandler(t)
332		const n = 40
333		var wg sync.WaitGroup
334		errs := make(chan error, n)
335		for i := 0; i < n; i++ {
336			wg.Add(1)
337			go func(i int) {
338				defer wg.Done()
339				w, _ := postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
340					"deviceId": "dev",
341					"changes":  []any{map[string]any{"id": fmt.Sprintf("id-%02d", i), "payload": map[string]any{"i": i}}},
342				})
343				if w.Code != 200 {
344					errs <- fmt.Errorf("post %d status %d: %s", i, w.Code, w.Body.String())
345				}
346			}(i)
347		}
348		wg.Wait()
349		close(errs)
350		for err := range errs {
351			t.Error(err)
352		}
353	
354		w, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc/changes?limit=1000")
355		if w.Code != 200 {
356			t.Fatal(w.Body.String())
357		}
358		if got := len(body["changes"].([]any)); got != n {
359			t.Fatalf("stored %d changes, want %d", got, n)
360		}
361		if body["nextCursor"].(float64) != n {
362			t.Fatalf("nextCursor = %v, want %d", body["nextCursor"], n)
363		}
364	}
