482			"change": map[string]any{"id": "cX", "payload": map[string]any{"z": 1}},
483		})
484		if w.Code != http.StatusBadRequest {
485			t.Fatalf("ahead base = %d", w.Code)
486		}
487	
488		// Same id repost -> idempotent with embedded result.
489		w, body = mergeBody(t, h, "doc", map[string]any{
490			"deviceId": "dev", "baseCursor": 1,
491			"change": map[string]any{"id": "c1", "payload": map[string]any{"a": 1}},
492		})
493		if w.Code != 200 || body["outcome"] != "idempotent" || body["cursor"].(float64) != 1 {
494			t.Fatalf("idempotent = %d %v", w.Code, body)
495		}
496		res := body["result"].(map[string]any)
497		if res["id"] != "c1" || res["created"] != false || res["cursor"].(float64) != 1 {
498			t.Fatalf("embedded result = %v", res)
499		}
500	
501		// Same id, different payload -> 409.
502		w, _ = mergeBody(t, h, "doc", map[string]any{
503			"deviceId": "dev", "baseCursor": 1,
504			"change": map[string]any{"id": "c1", "payload": map[string]any{"a": 2}},
505		})
506		if w.Code != http.StatusConflict {
507			t.Fatalf("conflict = %d body=%s", w.Code, w.Body.String())
508		}
509	
510		// Seed a second object {"b":2} at cursor 2.
511		w, _ = postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
512			"deviceId": "dev",
513			"changes":  []any{map[string]any{"id": "c2", "payload": map[string]any{"b": 2}}},
514		})
515		if w.Code != 200 {
516			t.Fatal(w.Body.String())
517		}
518	
519		// Stale client at baseCursor 1 posts {"c":3}: disjoint from later {"b":2} -> merged cursor 3.
520		w, body = mergeBody(t, h, "doc", map[string]any{
521			"deviceId": "dev", "baseCursor": 1,
522			"change": map[string]any{"id": "c3", "payload": map[string]any{"c": 3}},
523		})
524		if w.Code != 200 || body["outcome"] != "merged" || body["cursor"].(float64) != 3 {
525			t.Fatalf("merged = %d %v body=%s", w.Code, body, w.Body.String())
526		}
527	
528		// Stale client posts a payload colliding with later key "b" -> 409 zero write.
529		before, _, _ := s.ListChanges("doc", 0, 100)
530		w, _ = mergeBody(t, h, "doc", map[string]any{
531			"deviceId": "dev", "baseCursor": 0,
532			"change": map[string]any{"id": "c4", "payload": map[string]any{"b": 99}},
533		})
534		if w.Code != http.StatusConflict {
535			t.Fatalf("clash = %d body=%s", w.Code, w.Body.String())
536		}
537		after, _, _ := s.ListChanges("doc", 0, 100)
538		if len(after) != len(before) {
539			t.Fatalf("conflict changed row count: before=%d after=%d", len(before), len(after))
540		}
541	}
