211	// TestSealedAttachmentRejectsChunks covers post-seal immutability: once a
212	// finish has committed, every further chunk write — identical bytes, different
213	// bytes, even an out-of-range index — is ErrAttachmentSealed and the recorded
214	// state and content are unchanged. The rejection and the original bytes
215	// survive a restart.
216	func TestSealedAttachmentRejectsChunks(t *testing.T) {
217		path := filepath.Join(t.TempDir(), "test.db")
218		s, err := Open(path)
219		if err != nil {
220			t.Fatal(err)
221		}
222		mustRegisterDevice(t, s, "dev-1")
223	
224		content := []byte("hello world") // 11 bytes, chunks of 4: [hell][o wo][rld]
225		if _, err := s.CreateAttachment("dev-1", toAttachment("att-1", 11, 4, content)); err != nil {
226			t.Fatal(err)
227		}
228		for i, chunk := range [][]byte{[]byte("hell"), []byte("o wo"), []byte("rld")} {
229			if _, err := s.PutChunk("dev-1", "att-1", int64(i), chunk); err != nil {
230				t.Fatal(err)
231			}
232		}
233		res, err := s.CompleteAttachment("dev-1", "att-1")
234		if err != nil || !res.Complete {
235			t.Fatalf("complete = %+v %v", res, err)
236		}
237	
238		assertSealed := func(t *testing.T, s *Store) {
239			t.Helper()
240			// Byte-identical resubmission is no longer idempotent: it is rejected.
241			if _, err := s.PutChunk("dev-1", "att-1", 0, []byte("hell")); !errors.Is(err, ErrAttachmentSealed) {
242				t.Fatalf("identical chunk after seal = %v, want ErrAttachmentSealed", err)
243			}
244			// Different bytes at an existing index are rejected too.
245			if _, err := s.PutChunk("dev-1", "att-1", 0, []byte("HELL")); !errors.Is(err, ErrAttachmentSealed) {
246				t.Fatalf("conflicting chunk after seal = %v, want ErrAttachmentSealed", err)
247			}
248			// Even an out-of-range write hits the seal before any shape check.
249			if _, err := s.PutChunk("dev-1", "att-1", 7, []byte("xxxx")); !errors.Is(err, ErrAttachmentSealed) {
250				t.Fatalf("out-of-range chunk after seal = %v, want ErrAttachmentSealed", err)
251			}
252			// The recorded state and content are unchanged.
253			a, indices, err := s.GetAttachment("dev-1", "att-1")
254			if err != nil || !a.Complete || len(indices) != 3 {
255				t.Fatalf("sealed attachment = %+v %v %v", a, indices, err)
256			}
257			data, err := s.GetAttachmentChunk("dev-1", "att-1", 0)
258			if err != nil || string(data) != "hell" {
259				t.Fatalf("chunk 0 after rejected writes = %q %v", data, err)
260			}
261			// A repeat finish still returns the first recorded result.
262			again, err := s.CompleteAttachment("dev-1", "att-1")
263			if err != nil || again != res {
264				t.Fatalf("repeat complete = %+v %v, want %+v", again, err, res)
265			}
266		}
267		assertSealed(t, s)
268		if err := s.Close(); err != nil {
269			t.Fatal(err)
270		}
271	
272		// After a restart the seal still holds and the original bytes are intact.
273		s, err = Open(path)
274		if err != nil {
275			t.Fatal(err)
276		}
277		defer func() { _ = s.Close() }()
278		assertSealed(t, s)
279	}
