281	func TestAttachmentsPersistAcrossReopen(t *testing.T) {
282		path := filepath.Join(t.TempDir(), "test.db")
283		s, err := Open(path)
284		if err != nil {
285			t.Fatal(err)
286		}
287		mustRegisterDevice(t, s, "dev-1")
288		content := []byte("hello world")
289		if _, err := s.CreateAttachment("dev-1", toAttachment("att-1", 11, 4, content)); err != nil {
290			t.Fatal(err)
291		}
292		if _, err := s.PutChunk("dev-1", "att-1", 0, []byte("hell")); err != nil {
293			t.Fatal(err)
294		}
295		if err := s.Close(); err != nil {
296			t.Fatal(err)
297		}
298	
299		s, err = Open(path)
300		if err != nil {
301			t.Fatal(err)
302		}
303		defer func() { _ = s.Close() }()
304	
305		// Idempotency decisions survive the restart.
306		created, err := s.CreateAttachment("dev-1", toAttachment("att-1", 11, 4, content))
307		if err != nil || created {
308			t.Fatalf("create after reopen = %v %v, want idempotent", created, err)
309		}
310		created, err = s.PutChunk("dev-1", "att-1", 0, []byte("hell"))
311		if err != nil || created {
312			t.Fatalf("chunk after reopen = %v %v, want idempotent", created, err)
313		}
314		// The upload resumes and finishes.
315		if _, err := s.PutChunk("dev-1", "att-1", 1, []byte("o wo")); err != nil {
316			t.Fatal(err)
317		}
318		if _, err := s.PutChunk("dev-1", "att-1", 2, []byte("rld")); err != nil {
319			t.Fatal(err)
320		}
321		res, err := s.CompleteAttachment("dev-1", "att-1")
322		if err != nil || !res.Complete || res.Reused {
323			t.Fatalf("complete after reopen = %+v %v", res, err)
324		}
325	}
