327	// toAttachment builds the create-time metadata for content with the given
328	// chunking.
329	func toAttachment(id string, total, chunk int64, content []byte) Attachment {
330		return Attachment{
331			ID:         id,
332			TotalBytes: total,
333			ChunkSize:  chunk,
334			SHA256:     digestOf(content),
335		}
336	}
