386	// TestGetAttachmentChunkRange rejects an out-of-range index as invalid (400 at
387	// the HTTP layer) even when the attachment is otherwise known, while an
388	// in-range index without a chunk stays a not-found.
389	func TestGetAttachmentChunkRange(t *testing.T) {
390		s, err := Open("")
391		if err != nil {
392			t.Fatal(err)
393		}
394		defer func() { _ = s.Close() }()
395		mustRegisterDevice(t, s, "dev-1")
396	
397		content := []byte("hello world") // 11 bytes / 4 -> 3 chunks (0..2)
398		if _, err := s.CreateAttachment("dev-1", toAttachment("att-1", 11, 4, content)); err != nil {
399			t.Fatal(err)
400		}
401	
402		var invalid *ErrChunkInvalid
403		if _, err := s.GetAttachmentChunk("dev-1", "att-1", 3); !errors.As(err, &invalid) {
404			t.Fatalf("out-of-range read = %v, want *ErrChunkInvalid", err)
405		}
406		if _, err := s.GetAttachmentChunk("dev-1", "att-1", 0); !errors.Is(err, ErrChunkNotFound) {
407			t.Fatalf("in-range missing chunk = %v, want ErrChunkNotFound", err)
408		}
409		if _, err := s.GetAttachmentChunk("dev-1", "nope", 0); !errors.Is(err, ErrAttachmentNotFound) {
410			t.Fatalf("unknown attachment = %v, want ErrAttachmentNotFound", err)
